"""Interfaz local de operador para configurar y probar mosAIc."""

PAGE = r'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>mosAIc · Panel de control</title>
<style>
:root{color-scheme:light;--ink:#1f2638;--muted:#687189;--line:#e2e5ef;--accent:#5946d8;--bg:#f6f6fb;--bad:#a63449}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,sans-serif}
header{background:#fff;border-bottom:1px solid var(--line)}.top{max-width:1420px;margin:auto;padding:16px 24px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.brand{font-size:24px;font-weight:800;letter-spacing:-1px}.brand span{color:var(--accent)}.sub{color:var(--muted);font-size:13px}.scope{margin-left:auto;border:1px solid var(--line);border-radius:30px;padding:5px 12px;font-size:12px;color:var(--muted)}
main{max-width:1420px;margin:auto;padding:28px 24px 60px}.intro h1{font-size:29px;letter-spacing:-1px;margin:0}.intro p{color:var(--muted);margin:5px 0 22px}.grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);gap:18px;align-items:start}
.stack{display:grid;gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 5px 24px #1e214008}.card h2{font-size:17px;margin:0}.desc{color:var(--muted);font-size:13px;margin:5px 0 16px}.section-head{display:flex;align-items:start;gap:10px}.badge{font-size:11px;font-weight:700;color:var(--accent);background:#f0edff;padding:4px 9px;border-radius:30px;margin-left:auto;white-space:nowrap}
label{display:block;font-size:13px;font-weight:650;margin:12px 0 5px}input,textarea,select{width:100%;background:#fff;border:1px solid #d7dbe8;border-radius:8px;padding:9px 10px;color:var(--ink);font:inherit}textarea{resize:vertical;min-height:85px}textarea.prompt{min-height:260px;font:12px/1.55 ui-monospace,monospace}select[multiple]{min-height:82px}input:focus,textarea:focus,select:focus{outline:2px solid #b6acf9;outline-offset:1px}
.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}button{border:0;border-radius:8px;background:var(--accent);color:white;font:inherit;font-size:13px;font-weight:700;padding:9px 14px;cursor:pointer}button.secondary{background:#f0eff9;color:#4f419e}button:disabled{opacity:.5;cursor:not-allowed}.hint{font-size:12px;color:var(--muted);margin:8px 0 0}.msg{margin-top:12px;padding:10px 12px;border-radius:8px;background:#f2f0ff;color:#473b9d;font-size:13px;white-space:pre-wrap}.msg.error{background:#fff0f2;color:var(--bad)}.msg:empty{display:none}.output{white-space:pre-wrap;overflow:auto;max-height:260px;background:#f7f7fb;border:1px solid var(--line);border-radius:8px;padding:12px;font:12px/1.5 ui-monospace,monospace}.output:empty{display:none}hr{border:0;border-top:1px solid var(--line);margin:20px 0}.checklist{display:flex;gap:10px;flex-wrap:wrap}.checklist label{margin:0;display:flex;align-items:center;gap:5px;font-weight:500}.checklist input{width:auto}.empty{color:var(--muted)}
@media(max-width:860px){.grid{grid-template-columns:1fr}.top,main{padding-left:16px;padding-right:16px}.scope{margin-left:0}.row{grid-template-columns:1fr}}
</style></head><body>
<header><div class="top"><div class="brand">mos<span>AI</span>c</div><div class="sub">Panel de control · demo local</div><div class="scope" id="scope">Cargando configuración…</div></div></header>
<main><div class="intro"><h1>Configura el guardrail</h1><p>Define qué se protege, ajusta los agentes y prueba cómo evoluciona el conocimiento.</p></div>
<div class="grid"><div class="stack">
<section class="card"><div class="section-head"><h2>Agentes y prompts</h2><span class="badge">4 AGENTES</span></div><p class="desc">Edita las instrucciones que usan los agentes en la API local.</p>
<label for="agent">Agente</label><select id="agent"><option value="ontology">Constructor de ontología</option><option value="adversary">Analista adversarial</option><option value="analyst">Analista de respuestas</option><option value="rewriter">Reformulador de catálogo</option></select>
<p class="hint" id="agent-help"></p><p class="hint" id="agent-secrets"></p><label for="prompt">Instrucciones del agente</label><textarea id="prompt" class="prompt" spellcheck="false"></textarea>
<div class="actions"><button id="save-prompt">Guardar prompt</button><button class="secondary" id="restore-prompt">Restaurar valor inicial</button></div><div class="msg" id="prompt-msg" role="status"></div>
<p class="hint">La política de secretos se entrega como contexto a los agentes de análisis. El reformulador de catálogo recibe una alternativa ya aprobada; el motor vuelve a validarla.</p></section>
<section class="card"><div class="section-head"><h2>Conocimiento y fuentes</h2><span class="badge">ONTOLOGÍA</span></div><p class="desc">Analiza un texto y revisa lo que el modelo propone antes de incorporarlo.</p>
<label for="source-id">Identificador de fuente</label><input id="source-id" placeholder="ejemplo: correo_01" maxlength="96">
<div class="row"><div><label for="source-day">Fecha</label><input id="source-day" type="date"></div><div><label for="source-users">¿Quién recibió esta fuente?</label><select id="source-users" multiple></select><p class="hint">Opcional. Sin selección, solo se agrega al contexto interno.</p></div></div>
<label for="source-text">Texto de la fuente</label><textarea id="source-text" placeholder="Pega aquí el contenido que conoce el agente…" maxlength="12000"></textarea>
<div class="actions"><button id="preview-source">Analizar fuente</button><button id="accept-source" class="secondary" disabled>Incorporar propuestas</button></div><div class="msg" id="source-msg" role="status"></div><pre class="output" id="source-output"></pre>
</section></div><div class="stack">
<section class="card"><div class="section-head"><h2>Secretos y acceso</h2><span class="badge">POLÍTICA</span></div><p class="desc">Define conclusiones protegidas. Los roles elegidos pueden recibirlas; las reglas y los datos siguen siendo parte del grafo.</p><p class="hint" id="empty-secrets"></p>
<label for="secret-select">Conclusión protegida</label><select id="secret-select"></select>
<label for="secret-id">Identificador</label><input id="secret-id" placeholder="ejemplo: contrato_firmado" pattern="[a-z][a-z0-9_]*" maxlength="96">
<label for="secret-desc">¿Qué conocimiento es sensible?</label><textarea id="secret-desc" placeholder="Describe la conclusión que se debe proteger…" maxlength="2000"></textarea>
<label for="secret-mode">¿Qué valores se protegen?</label><select id="secret-mode"><option value="any">Cualquier valor</option><option value="listed">Solo valores específicos</option></select>
<p class="hint">«Cualquier valor» sirve para domicilios, votos u otros datos que no quieres enumerar. Se protege cada valor que el sistema logre representar.</p>
<div id="status-fields" hidden><label for="secret-status">Valores específicos</label><input id="secret-status" placeholder="signed, unsigned"><p class="hint">Identificadores separados por comas, en minúsculas y sin espacios.</p></div>
<div class="row"><div><label for="absolute">Umbral absoluto</label><input id="absolute" type="number" min="0" max="1" step="0.05" value="0.75"></div><div><label for="increase">Umbral de aumento</label><input id="increase" type="number" min="0" max="1" step="0.05" value="0.45"></div></div>
<label>Roles con permiso directo para esta conclusión</label><div class="checklist" id="roles"></div><p class="hint">Los roles también pueden heredar permisos de sus roles superiores.</p>
<div class="actions"><button id="save-secret">Guardar secreto</button><button class="secondary" id="new-secret">Nuevo secreto</button></div><div class="msg" id="secret-msg" role="status"></div>
<p class="hint">Los umbrales no están calibrados. Puedes ampliar la protección, pero el panel no permite eliminar valores protegidos existentes. La cobertura depende de la extracción y las fuentes disponibles.</p>
<hr><h2>Conceptos y relaciones</h2><p class="desc">Agrega los predicados que usarán las reglas intermedias de la ontología.</p>
<label for="vocab-name">Identificador del concepto</label><input id="vocab-name" placeholder="ejemplo: documento_firmado" maxlength="96">
<label for="vocab-desc">Significado</label><input id="vocab-desc" placeholder="Describe cuándo corresponde este concepto" maxlength="2000">
<div class="actions"><button class="secondary" id="save-vocab">Guardar concepto</button></div><p class="hint" id="vocab-list"></p><div class="msg" id="vocab-msg" role="status"></div></section>
<section class="card"><div class="section-head"><h2>Probar una respuesta</h2><span class="badge">TEXTO LIBRE</span></div><p class="desc">La respuesta la aporta un agente externo o la escribes tú. mosAIc la evalúa para un destinatario.</p>
<div class="row"><div><label for="review-user">Destinatario</label><select id="review-user"></select></div><div><label for="review-day">Fecha</label><input type="date" id="review-day"></div></div>
<label for="question">Tarea o pregunta</label><input id="question" placeholder="¿Qué necesita saber el destinatario?" maxlength="4000">
<label for="answer">Respuesta del agente</label><textarea id="answer" placeholder="Escribe el borrador que quieres evaluar…" maxlength="4000"></textarea>
<div class="actions"><button id="check-answer">Evaluar respuesta</button><button class="secondary" id="revise-answer" disabled>Evaluar reformulación</button><button class="secondary" id="deliver-answer" disabled>Confirmar entrega</button></div>
<p class="hint">Para reformular, edita el borrador y vuelve a evaluarlo. Solo una respuesta aprobada puede entregarse.</p><div class="msg" id="review-msg" role="status"></div><pre class="output" id="inbox"></pre>
<details><summary>Ver análisis privado</summary><p class="hint">Requiere iniciar la API con MOSAIC_OPERATOR_TOKEN y escribir ese mismo token aquí.</p><label for="operator-token">Token de operador</label><input id="operator-token" type="password" autocomplete="off"><div class="actions"><button class="secondary" id="view-trace">Ver detalle de la evaluación</button></div><div class="msg" id="trace-msg" role="status"></div><pre class="output" id="trace"></pre></details>
</section></div></div></main>
<script>
const $ = id => document.getElementById(id);
let config = null, activeAgent = 'ontology', sourcePreview = null, review = null;
const agentHelp = {ontology:'Extrae hechos y propone reglas desde las fuentes internas.', adversary:'Explora qué podría inferir un destinatario con su historial.', analyst:'Representa el borrador en el vocabulario y verifica si responde a la tarea.', rewriter:'Reformula hacia una alternativa del catálogo para el endpoint automático.'};
function message(id, text, error=false){const node=$(id);node.textContent=text;node.className='msg'+(error?' error':'')}
function options(id, values){const el=$(id);el.replaceChildren();for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;el.append(option)}}
async function request(url, method='GET', body){const r=await fetch(url,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw new Error('Respuesta inesperada del servidor')};if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Revisa los datos ingresados');return data}
function uid(prefix){return prefix+'_'+crypto.randomUUID().replaceAll('-','')}
function agentView(){activeAgent=$('agent').value;$('prompt').value=config.prompts[activeAgent];$('agent-help').textContent=agentHelp[activeAgent];const families=Object.entries(config.families);$('agent-secrets').textContent=activeAgent==='rewriter'?'Este agente recibe una alternativa ya aprobada, no la lista de secretos.':families.length?'Secretos definidos en la política: '+families.map(([id,f])=>id+' ('+f.description+')').join('; '):'Aún no hay secretos configurados.';message('prompt-msg','')}
function renderRoles(selected=[]){const box=$('roles');box.replaceChildren();for(const role of config.roles){const label=document.createElement('label'),cb=document.createElement('input');cb.type='checkbox';cb.value=role;cb.checked=selected.includes(role);label.append(cb,document.createTextNode(role));box.append(label)}}
function secretMode(){ $('status-fields').hidden=$('secret-mode').value==='any' }
function secretView(){const name=$('secret-select').value;const family=config.families[name];$('secret-id').value=name||'';$('secret-id').readOnly=!!family;$('secret-desc').value=family?.description||'';$('secret-mode').value=(family?.any_value??true)?'any':'listed';$('secret-status').value=family?.statuses.join(', ')||'';secretMode();$('absolute').value=family?.absolute??.75;$('increase').value=family?.increase??.45;renderRoles(Object.keys(config.grants).filter(r=>config.grants[r].includes(name)))}
async function loadConfig(){config=await request('/v1/demo/config');$('scope').textContent=config.scope.org+' / '+config.scope.operation;options('review-user',config.users);options('source-users',config.users);options('secret-select',Object.keys(config.families));$('empty-secrets').textContent=Object.keys(config.families).length?'':'Aún no hay secretos específicos. El analista adversarial evaluará posibles datos sensibles.';$('source-day').value=config.day;$('review-day').value=config.day;$('vocab-list').textContent='Disponibles: '+Object.keys(config.vocabulary).join(', ');agentView();secretView()}
$('agent').addEventListener('change',agentView);$('secret-select').addEventListener('change',secretView);$('secret-mode').addEventListener('change',secretMode);
$('save-prompt').onclick=async()=>{try{await request('/v1/demo/prompts/'+encodeURIComponent(activeAgent),'PUT',{prompt:$('prompt').value});config.prompts[activeAgent]=$('prompt').value;message('prompt-msg','Prompt guardado. Las revisiones anteriores deberán comprobarse de nuevo.')}catch(e){message('prompt-msg',e.message,true)}};
$('restore-prompt').onclick=()=>{if(config){$('prompt').value=config.default_prompts[activeAgent];message('prompt-msg','Valor inicial restaurado en el editor. Guarda para aplicarlo.')}};
$('new-secret').onclick=()=>{$('secret-select').selectedIndex=-1;secretView();$('secret-id').focus()};
$('save-secret').onclick=async()=>{try{const name=$('secret-id').value.trim(),any_value=$('secret-mode').value==='any';const payload={description:$('secret-desc').value,any_value,statuses:any_value?[]:$('secret-status').value.split(',').map(s=>s.trim()).filter(Boolean),absolute:Number($('absolute').value),increase:Number($('increase').value),allowed_roles:[...$('roles').querySelectorAll('input:checked')].map(e=>e.value)};await request('/v1/demo/secrets/'+encodeURIComponent(name),'PUT',payload);const savedName=name;await loadConfig();$('secret-select').value=savedName;secretView();message('secret-msg','Secreto y permisos guardados.')}catch(e){message('secret-msg',e.message,true)}};
$('save-vocab').onclick=async()=>{try{const name=$('vocab-name').value.trim(),description=$('vocab-desc').value;await request('/v1/demo/vocabulary/'+encodeURIComponent(name),'PUT',{description});config.vocabulary[name]=description;$('vocab-list').textContent='Disponibles: '+Object.keys(config.vocabulary).join(', ');message('vocab-msg','Concepto guardado.')}catch(e){message('vocab-msg',e.message,true)}};
function sourceBody(){return {origin:$('source-id').value.trim(),at:$('source-day').value,text:$('source-text').value,recipients:[...$('source-users').selectedOptions].map(o=>o.value)}}
function invalidateSource(){sourcePreview=null;$('accept-source').disabled=true}$('source-id').oninput=invalidateSource;$('source-text').oninput=invalidateSource;$('source-day').onchange=invalidateSource;$('source-users').onchange=invalidateSource;
$('preview-source').onclick=async()=>{invalidateSource();try{message('source-msg','Analizando fuente con Claude…');const body=sourceBody();const data=await request('/v1/demo/sources/preview','POST',body);if(JSON.stringify(body)!==JSON.stringify(sourceBody())){message('source-msg','La fuente cambió durante el análisis; vuelve a analizarla.',true);return}sourcePreview=data.preview_id;$('source-output').textContent=JSON.stringify(data.observations,null,2);$('accept-source').disabled=!sourcePreview;message('source-msg',sourcePreview?data.observations.length+' propuestas. Revisa el detalle antes de incorporar.':(data.message||'No se extrajeron hechos. La fuente no se incorporó.'),!sourcePreview)}catch(e){message('source-msg',e.message,true)}};
$('accept-source').onclick=async()=>{try{const data=await request('/v1/demo/sources/'+encodeURIComponent(sourcePreview)+'/accept','POST');invalidateSource();message('source-msg',data.accepted?'Propuestas incorporadas al historial.':'Esta fuente ya estaba incorporada.')}catch(e){message('source-msg',e.message,true)}};
function reviewButtons(status){$('revise-answer').disabled=status!=='revise'&&status!=='review';$('deliver-answer').disabled=status!=='approved'}
$('check-answer').onclick=async()=>{try{review=null;reviewButtons('');message('review-msg','Evaluando con Claude y el motor de inferencia…');const user=$('review-user').value,question=$('question').value,day=$('review-day').value,text=$('answer').value;const data=await request('/v1/reviews','POST',{review_id:uid('review'),user,task:'freeform',question,text,day});review={id:data.review_id,user,question,day,text};reviewButtons(data.status);message('review-msg',data.status==='approved'?'Aprobada para entrega.':'Necesita reformulación. '+(data.feedback||''))}catch(e){message('review-msg',e.message,true)}};
function sameTask(){return review&&$('review-user').value===review.user&&$('question').value===review.question&&$('review-day').value===review.day}
$('revise-answer').onclick=async()=>{if(!review)return;if(!sameTask()){message('review-msg','La tarea, fecha o destinatario cambió. Inicia una evaluación nueva.',true);return}try{message('review-msg','Evaluando reformulación…');const text=$('answer').value;const data=await request('/v1/reviews/'+encodeURIComponent(review.id)+'/revisions','POST',{revision_id:uid('revision'),user:review.user,text});review.text=text;reviewButtons(data.status);message('review-msg',data.status==='approved'?'Reformulación aprobada para entrega.':'Necesita otra reformulación. '+(data.feedback||''))}catch(e){message('review-msg',e.message,true)}};
$('deliver-answer').onclick=async()=>{if(!review)return;if(!sameTask()||$('answer').value!==review.text){message('review-msg','El texto, tarea, fecha o destinatario cambió. Evalúa de nuevo antes de entregar.',true);return}try{const data=await request('/v1/reviews/'+encodeURIComponent(review.id)+'/deliver','POST',{user:review.user});reviewButtons('');message('review-msg',data.text?'Entregado: '+data.text:'No se entregó: '+(data.reason||'requiere revisión'));const inbox=await request('/v1/inbox/'+encodeURIComponent(review.user));$('inbox').textContent='Bandeja de '+review.user+'\n'+(inbox.messages.map(m=>m.text).join('\n')||'Sin entregas.')}catch(e){message('review-msg',e.message,true)}};
$('view-trace').onclick=async()=>{if(!review){message('trace-msg','Primero evalúa una respuesta.',true);return}try{const token=$('operator-token').value;const response=await fetch('/v1/reviews/'+encodeURIComponent(review.id)+'?user='+encodeURIComponent(review.user),{headers:{'X-Mosaic-Operator-Token':token}});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'No se pudo consultar el detalle');$('trace').textContent=JSON.stringify(data.trace,null,2);message('trace-msg','Detalle privado de la evaluación.')}catch(e){message('trace-msg',e.message,true)}};
loadConfig().catch(e=>message('prompt-msg','No se pudo cargar el panel: '+e.message,true));
</script></body></html>'''
